import{_ as o,o as d,c,a5 as t}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"HJ30 字符串合并处理","description":"较难 通过率：23.43% 时间限制：1秒 空间限制：32M 知识点 字符串 排序 描述 按照指定规则对输入的字符串进行处理。 详细描述： 第一步：将输入的两个字符串str1和str2进行前后合并。如给定字符串 \\"dec\\" 和字符串 \\"fab\\" ， 合并后生成的字符串为 \\"dec。","frontmatter":{"title":"HJ30 字符串合并处理","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"较难 通过率：23.43% 时间限制：1秒 空间限制：32M 知识点 字符串 排序 描述 按照指定规则对输入的字符串进行处理。 详细描述： 第一步：将输入的两个字符串str1和str2进行前后合并。如给定字符串 \\"dec\\" 和字符串 \\"fab\\" ， 合并后生成的字符串为 \\"dec。","sidebarWeight":89,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为较难题/HJ30 字符串合并处理.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为较难题/HJ30 字符串合并处理.md","filePath":"posts/前端面试与实战/03-算法训练/华为较难题/HJ30 字符串合并处理.md"}'),a={name:"posts/前端面试与实战/03-算法训练/华为较难题/HJ30 字符串合并处理.md"};function r(l,e,i,s,n,u){return d(),c("div",null,[...e[0]||(e[0]=[t('<div><h1 id="hj30-字符串合并处理" tabindex="-1">HJ30 字符串合并处理 <a class="header-anchor" href="#hj30-字符串合并处理" aria-label="Permalink to &quot;HJ30 字符串合并处理&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ30 字符串合并处理”的核心思路，并能把它用于实际开发或面试表达。 较难 通过率：23.43% 时间限制：1秒 空间限制：32M 知识点==字符串====排序== <strong>描述</strong> 按照指定规则对输入的字符串进行处理。 详细描述： 第一步：将输入的两个字符串str1和str2进行前后合并。如给定字符串 &quot;dec&quot; 和字符串 &quot;fab&quot; ， 合并后生成的字符串为 &quot;decfab&quot; 第二步：对合并后的字符串进行排序，要求为：下标为奇数的字符和下标为偶数的字符分别从小到大排序。这里的下标的意思是字符在字符串中的位置。注意排序后在新串中仍需要保持原来的奇偶性。例如刚刚得到的字符串“decfab”，分别对下标为偶数的字符&#39;d&#39;、&#39;c&#39;、&#39;a&#39;和下标为奇数的字符&#39;e&#39;、&#39;f&#39;、&#39;b&#39;进行排序（生成 &#39;a&#39;、&#39;c&#39;、&#39;d&#39; 和 &#39;b&#39; 、&#39;e&#39; 、&#39;f&#39;），再依次分别放回原串中的偶数位和奇数位，新字符串变为“abcedf” 第三步：对排序后的字符串中的&#39;0&#39;~&#39;9&#39;、&#39;A&#39;~&#39;F&#39;和&#39;a&#39;~&#39;f&#39;字符，需要进行转换操作。 转换规则如下： 对以上需要进行转换的字符所代表的十六进制用二进制表示并倒序，然后再转换成对应的十六进制大写字符（注：字符 a~f 的十六进制对应十进制的10~15，大写同理）。 如字符 &#39;4&#39;，其二进制为 0100 ，则翻转后为 0010 ，也就是 2 。转换后的字符为 &#39;2&#39;。 如字符 ‘7’，其二进制为 0111 ，则翻转后为 1110 ，对应的十进制是14，转换为十六进制的大写字母为 &#39;E&#39;。 如字符 &#39;C&#39;，代表的十进制是 12 ，其二进制为 1100 ，则翻转后为 0011，也就是3。转换后的字符是 &#39;3&#39;。 根据这个转换规则，由第二步生成的字符串 “abcedf” 转换后会生成字符串 &quot;5D37BF&quot;。 数据范围：输入的字符串长度满足 1≤�≤100 1≤<em>n</em>≤100</p></blockquote><p><strong>输入描述：</strong> 样例输入两个字符串，用空格隔开。 <strong>输出描述：</strong> 输出转化后的结果。 <strong>示例1</strong> 输入： dec fab ==复制== 输出： 5D37BF ==复制== <strong>示例2</strong> 输入： ab CD ==复制== 输出： 3B5D ==复制== 说明： 合并后为abCD，按奇数位和偶数位排序后是CDab（请注意要按ascii码进行排序，所以C在a前面，D在b前面），转换后为3B5D <strong>示例3</strong> 输入： 123 15 ==复制== 输出： 88C4A</p><p>当然，这个表达式看起来相当复杂，因为它在一行中完成了多个转换步骤。这里是对<code>c</code>进行处理的步骤，假设<code>c</code>是一个十六进制字符（比如 <code>&#39;F&#39;</code>、<code>&#39;7&#39;</code>、<code>&#39;a&#39;</code>等）。我们将这个表达式分解成几个步骤：</p><ol><li><code>int(c, 16)</code>：将十六进制字符<code>c</code>转换为整数。</li></ol><ul><li>例如，如果<code>c = &#39;F&#39;</code>，则转换结果为<code>15</code>。</li></ul><ol start="2"><li><code>bin(...)[2:]</code>：使用<code>bin()</code>函数将步骤1得到的整数转换成二进制表示的字符串，然后<code>[2:]</code>切片操作去除掉前缀<code>&#39;0b&#39;</code>。</li></ol><ul><li>继续上面的例子，<code>15</code>转换为二进制是<code>&#39;0b1111&#39;</code>，去除前缀后是<code>&#39;1111&#39;</code>。</li></ul><ol start="3"><li><code>...zfill(4)</code>：确保二进制字符串长度至少为4位，如果不够则在前面填充零。由于一个十六进制数字最多可以表示4位二进制数，这一步骤确保了转换的一致性。</li></ol><ul><li>在这个例子中，<code>&#39;1111&#39;</code>已经是4位，所以这一步不会改变字符串。</li></ul><ol start="4"><li><code>...[::-1]</code>：将上一步得到的字符串反转，实现二进制位的翻转。</li></ol><ul><li><code>&#39;1111&#39;</code>反转后仍然是<code>&#39;1111&#39;</code>。如果考虑另一个字符，比如<code>&#39;E&#39;</code>转换后是<code>&#39;0111&#39;</code>，反转为<code>&#39;1110&#39;</code>。</li></ul><ol start="5"><li><code>int(..., 2)</code>：将翻转后的二进制字符串再次转换为整数。</li></ol><ul><li><code>&#39;1111&#39;</code>转换回整数是<code>15</code>，<code>&#39;1110&#39;</code>转换为整数是<code>14</code>。</li></ul><ol start="6"><li><code>hex(...)[2:]</code>：使用<code>hex()</code>函数将步骤5的整数转换成十六进制表示的字符串，然后<code>[2:]</code>切片操作去除掉前缀<code>&#39;0x&#39;</code>。</li></ol><ul><li><code>15</code>转换为十六进制是<code>&#39;0xf&#39;</code>，去除前缀后是<code>&#39;f&#39;</code>。<code>14</code>转换为十六进制是<code>&#39;0xe&#39;</code>，去除前缀后是<code>&#39;e&#39;</code>。</li></ul><ol start="7"><li><code>...upper()</code>：将得到的十六进制字符串转换为大写。</li></ol><ul><li><code>&#39;f&#39;</code>变为<code>&#39;F&#39;</code>，<code>&#39;e&#39;</code>变为<code>&#39;E&#39;</code>。</li></ul><p>整个表达式合起来就实现了将一个十六进制字符<code>c</code>转换为二进制，反转这个二进制表示，然后再将反转后的二进制表示转换回十六进制字符，并且转为大写的过程。</p><p>以<code>&#39;F&#39;</code>为例，整个过程是：</p><ol><li><code>&#39;F&#39;</code> -&gt; 15</li><li>15 -&gt; <code>&#39;1111&#39;</code></li><li><code>&#39;1111&#39;</code> -&gt; <code>&#39;1111&#39;</code>（长度已经是4位）</li><li><code>&#39;1111&#39;</code> -&gt; <code>&#39;1111&#39;</code>（反转）</li><li><code>&#39;1111&#39;</code> -&gt; 15</li><li>15 -&gt; <code>&#39;f&#39;</code></li><li><code>&#39;f&#39;</code> -&gt; <code>&#39;F&#39;</code></li></ol><p>这个过程对于不同的字符会有不同的转换结果，关键在于二进制翻转这一步。</p><h1 id="这个函数用来把两个英文单词变成一个特别的密码" tabindex="-1">这个函数用来把两个英文单词变成一个特别的密码 <a class="header-anchor" href="#这个函数用来把两个英文单词变成一个特别的密码" aria-label="Permalink to &quot;这个函数用来把两个英文单词变成一个特别的密码&quot;">​</a></h1><p>def process_strings(str1, str2):</p><h1 id="首先-我们把两个单词放在一起-像是最好的朋友一样" tabindex="-1">首先，我们把两个单词放在一起，像是最好的朋友一样 <a class="header-anchor" href="#首先-我们把两个单词放在一起-像是最好的朋友一样" aria-label="Permalink to &quot;首先，我们把两个单词放在一起，像是最好的朋友一样&quot;">​</a></h1><p>merged_str = str1 + str2</p><h1 id="然后-我们要给这些字母分组-一组是奇数位置的-一组是偶数位置的" tabindex="-1">然后，我们要给这些字母分组，一组是奇数位置的，一组是偶数位置的 <a class="header-anchor" href="#然后-我们要给这些字母分组-一组是奇数位置的-一组是偶数位置的" aria-label="Permalink to &quot;然后，我们要给这些字母分组，一组是奇数位置的，一组是偶数位置的&quot;">​</a></h1><p>even_chars = sorted(merged_str[::2]) # 偶数位置的字母，比如在&quot;apple&quot;里，就是&quot;a&quot;和&quot;l&quot; odd_chars = sorted(merged_str[1::2]) # 奇数位置的字母，比如在&quot;apple&quot;里，就是&quot;p&quot;、&quot;p&quot;和&quot;e&quot;</p><h1 id="接下来-我们按顺序把这些字母重新排列起来-保持它们原来是奇数位置还是偶数位置" tabindex="-1">接下来，我们按顺序把这些字母重新排列起来，保持它们原来是奇数位置还是偶数位置 <a class="header-anchor" href="#接下来-我们按顺序把这些字母重新排列起来-保持它们原来是奇数位置还是偶数位置" aria-label="Permalink to &quot;接下来，我们按顺序把这些字母重新排列起来，保持它们原来是奇数位置还是偶数位置&quot;">​</a></h1><p>sorted_str = &#39;&#39;.join( even_chars[i//2] if i % 2 == 0 else odd_chars[i//2] for i in range(len(merged_str)))</p><h1 id="现在-我们开始魔法转换-把一些特别的字母变成它们的秘密形式" tabindex="-1">现在，我们开始魔法转换，把一些特别的字母变成它们的秘密形式 <a class="header-anchor" href="#现在-我们开始魔法转换-把一些特别的字母变成它们的秘密形式" aria-label="Permalink to &quot;现在，我们开始魔法转换，把一些特别的字母变成它们的秘密形式&quot;">​</a></h1><p>def convert_hex_char(c):</p><h1 id="如果这个字母是0到9或者是a到f-无论大小写" tabindex="-1">如果这个字母是0到9或者是a到f（无论大小写） <a class="header-anchor" href="#如果这个字母是0到9或者是a到f-无论大小写" aria-label="Permalink to &quot;如果这个字母是0到9或者是a到f（无论大小写）&quot;">​</a></h1><p>if c.isdigit() or (c.lower() &gt;= &#39;a&#39; and c.lower() &lt;= &#39;f&#39;):</p><h1 id="我们先把它变成一个秘密数字-然后变成二进制-翻转过来-再变回秘密数字-最后大写" tabindex="-1">我们先把它变成一个秘密数字，然后变成二进制，翻转过来，再变回秘密数字，最后大写 <a class="header-anchor" href="#我们先把它变成一个秘密数字-然后变成二进制-翻转过来-再变回秘密数字-最后大写" aria-label="Permalink to &quot;我们先把它变成一个秘密数字，然后变成二进制，翻转过来，再变回秘密数字，最后大写&quot;">​</a></h1><p>return hex(int(bin(int(c, 16))[2:].zfill(4)[::-1], 2))[2:].upper()</p><h1 id="如果这个字母没有什么特别-就保持原样" tabindex="-1">如果这个字母没有什么特别，就保持原样 <a class="header-anchor" href="#如果这个字母没有什么特别-就保持原样" aria-label="Permalink to &quot;如果这个字母没有什么特别，就保持原样&quot;">​</a></h1><p>return c</p><h1 id="最后-我们用魔法把每个字母都变成它的秘密形式-并把它们连接起来-就完成了" tabindex="-1">最后，我们用魔法把每个字母都变成它的秘密形式，并把它们连接起来，就完成了 <a class="header-anchor" href="#最后-我们用魔法把每个字母都变成它的秘密形式-并把它们连接起来-就完成了" aria-label="Permalink to &quot;最后，我们用魔法把每个字母都变成它的秘密形式，并把它们连接起来，就完成了&quot;">​</a></h1><p>result = &#39;&#39;.join(convert_hex_char(c) for c in sorted_str) return result</p><h1 id="我们从书本-控制台输入-里读取两个单词" tabindex="-1">我们从书本（控制台输入）里读取两个单词 <a class="header-anchor" href="#我们从书本-控制台输入-里读取两个单词" aria-label="Permalink to &quot;我们从书本（控制台输入）里读取两个单词&quot;">​</a></h1><p>input_str = input().split()</p><h1 id="使用我们的魔法-函数-处理这两个单词-并展示它们变成的密码" tabindex="-1">使用我们的魔法（函数）处理这两个单词，并展示它们变成的密码 <a class="header-anchor" href="#使用我们的魔法-函数-处理这两个单词-并展示它们变成的密码" aria-label="Permalink to &quot;使用我们的魔法（函数）处理这两个单词，并展示它们变成的密码&quot;">​</a></h1><p>print(process_strings(input_str[0], input_str[1]))</p></div>',1)])])}const f=o(a,[["render",r]]);export{p as __pageData,f as default};
